/**
 * The Gallows Pardon — structural test generated by compile:encounter (THR-1246).
 * Expected values are baked from the content package, so this file asserts the
 * encounter's actual shape rather than any template's.
 */

import { describe, expect, it } from 'vitest';
import { GALLOWS_PARDON_TEMPLATE } from '../gallows-pardon';
import { expandSettings } from '../../settingClasses';
import { drawConsequenceHand, handAfterSwap } from '../../content-eval/consequenceDraw';

describe("The Gallows Pardon — template structure", () => {
  it('carries its identity', () => {
    expect(GALLOWS_PARDON_TEMPLATE.id).toBe('encounter.town.gallows_pardon');
    expect(GALLOWS_PARDON_TEMPLATE.reach).toBe('heart');
    expect(GALLOWS_PARDON_TEMPLATE.rarityTier).toBe(2);
    expect(GALLOWS_PARDON_TEMPLATE.steps).toHaveLength(2);
  });

  it('step 0 deals the authored hand', () => {
    const step = GALLOWS_PARDON_TEMPLATE.steps[0];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['gallows.soften_hard_hearts', 'gallows.slow_the_hour']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['spirit', 'time']);
  });

  it('step 1 deals the authored hand', () => {
    const step = GALLOWS_PARDON_TEMPLATE.steps[1];
    if (!('narrativeTemplate' in step)) throw new Error('expected a plain step');
    expect((step.nudges ?? []).map(nudge => nudge.id)).toEqual(['gallows.press_the_conscience', 'gallows.find_the_right_words']);
    const spheres = [...new Set((step.nudges ?? []).map(nudge => nudge.sphere).filter(Boolean))].sort();
    expect(spheres).toEqual(['mind']);
  });
  it('derives its location subtypes from the declared envelope', () => {
    expect(GALLOWS_PARDON_TEMPLATE.settings).toEqual(['urban']);
    expect(GALLOWS_PARDON_TEMPLATE.locationSubtypes).toEqual(expandSettings(['urban']));
  });

  it('records exactly the hand its id draws (binding, THR-1145)', () => {
    expect(GALLOWS_PARDON_TEMPLATE.consequenceDraw).toEqual(['relationship', 'story_seed']);
    expect(GALLOWS_PARDON_TEMPLATE.consequenceDraw).toEqual(
      handAfterSwap(
        drawConsequenceHand({
          templateId: 'encounter.town.gallows_pardon',
          reach: 'heart',
          rarityTier: 2,
        }),
        GALLOWS_PARDON_TEMPLATE.consequenceSwap,
      ),
    );
  });
});
